INSERT INTO `culture_referenceblock` VALUES (6611,'Amos Rappaport. 1969.House, Form, and Culture. Prentice-Hall, Inc, New Jersey.',NULL),(6612,'Government of India. n.d. Ahmednagar: Ahmednagar Fort. Maharashtra Tourism. Accessed on May 7, 2025.','https://maharashtratourism.gov.in/fort/ahmednagar/#:~:text=The%20Architecture&text=With%2024%20mighty%20bastions%2C%20massive,battles%2C%20bravery%2C%20and%20resilience'),(6613,'M Singh and S Vinodh Kumar. 2019. Architechtural features and characterization of 16th century Indian Monument Farah Bagh, Ahmed Nagar, India. International Journal of Architectural Heritage. 14. 10.1080/15583058.2019.1610524.','https://www.researchgate.net/publication/332935786_Architechtural_features_and_characterization_of_16th_century_Indian_Monument_Farah_Bagh_Ahmed_Nagar_India'),(6614,'Shree Datta Devasthan Trust. n.d. Shree Datta Kshetra. Shree Datta Devasthan Trust. Accessed on May 7, 2025.','https://dattadevasthan.org/shree-datta-kshetra.html'),(6615,'Sigfried Giedion. 1959. Space, Time, & Architecture. 3rd ed. Harvard University Press.',NULL),(6616,'Tour My India. n.d. Bagh Rauza Ahmednagar. Tour My India. Accessed on May 7, 2025.','https://www.tourmyindia.com/states/maharashtra/bagh-rauza-ahmednagar.html'),(6617,'Tour My India. n.d. Salabat Khan Tomb Ahmednagar. Tour My India. Accessed on May 7, 2025.','https://www.tourmyindia.com/states/maharashtra/salabat-khan-tomb-ahmednagar.html'),(6684,'Santosh Khedlekar. 2021.Lavani through the Ages in Pune.Sahapedia.https://map.sahapedia.org/article/Lavani-through-the-Ages-in-Pune/6195','https://map.sahapedia.org/article/Lavani-through-the-Ages-in-Pune/6195'),(6685,'Amey Tirodkar. 2021.Lavani Artists from Maharashtra Struggle to Make Ends Meet Amid Pandemic.Newsclick.https://www.newsclick.in/lavani-artists-maharashtra-struggle-make-ends-meet-amid-pandemic','https://www.newsclick.in/lavani-artists-maharashtra-struggle-make-ends-meet-amid-pandemic'),(6686,'Maharashtra State Gazetteers. 1976.Ahmadnaga